<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\{AuditLog,Promotion}; use Illuminate\Http\{RedirectResponse,Request}; use Illuminate\Support\Str; use Illuminate\View\View;
class PromotionController extends Controller {public function index():View{return view('admin.promotions.index',['promotions'=>Promotion::latest()->paginate(10)]);} public function store(Request $r):RedirectResponse{$d=$this->valid($r);$p=Promotion::create($d+['slug'=>Str::slug($d['title']).'-'.Str::lower(Str::random(5)),'is_active'=>$r->boolean('is_active'),'is_featured'=>$r->boolean('is_featured')]);AuditLog::record('promotion.created',$p);return back()->with('success','Content item created.');} public function update(Request $r,Promotion $promotion):RedirectResponse{$old=$promotion->toArray();$promotion->update($this->valid($r)+['is_active'=>$r->boolean('is_active'),'is_featured'=>$r->boolean('is_featured')]);AuditLog::record('promotion.updated',$promotion,$old,$promotion->toArray());return back()->with('success','Content item updated.');} private function valid(Request $r):array{return $r->validate(['title'=>'required|string|max:160','type'=>'required|in:promotion,featured_offer,local_guide,testimonial,seasonal_message,booking_notice,homepage_section','summary'=>'nullable|string|max:500','body'=>'nullable|string|max:10000','cta_label'=>'nullable|string|max:80','cta_url'=>'nullable|string|max:500','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after_or_equal:starts_at','sort_order'=>'nullable|integer|min:0']);}}
